namespace GodTreeXOwais.Runtime; public sealed class AgentRouter{readonly Dictionary<string,IAgentProvider> providers=new(StringComparer.OrdinalIgnoreCase);public AgentRouter(params IAgentProvider[] initial){foreach(var p in initial)providers[p.Id]=p;}public void Register(IAgentProvider p)=>providers[p.Id]=p;public IAgentProvider Resolve(string? id=null)=>id!=null&&providers.TryGetValue(id,out var p)?p:providers.Values.First();}